// ServeHTTP is the main entry point for routing requests in Mux.
func (mx *Mux) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	// Check if route context is already present, otherwise allocate one
	rctx, _ := r.Context().Value(RouteCtxKey).(*Context)
	if rctx == nil {
		rctx = NewRouteContext()
		r = r.WithContext(context.WithValue(r.Context(), RouteCtxKey, rctx))
	}

	// Route path resolution
	routePath := r.URL.RawPath
	if routePath == "" {
		routePath = r.URL.Path
	}
	if routePath == "" {
		routePath = "/"
	}

	// Match route against tree
	if fn := mx.tree.FindRoute(rctx, r.Method, routePath); fn != nil {
		fn.ServeHTTP(w, r)
		return
	}

	// Fallback to MethodNotAllowed or NotFound
	mx.handleNotFound(w, r, rctx)
}
